import '@kerfjs/ui/layout.css';
import './project-search.css';

import { TokenSearchField, placeTokenSearchCaret, readTokenSearchField } from '@kerfjs/ui/token-search-field';
import { delegate, signal } from 'kerfjs';

type SearchToken = { id: string; label: string };
const initialTokens: SearchToken[] = [{ id: 'status:open', label: 'Status: Open' }, { id: 'owner:me', label: 'Owner: Me' }];

export function createProjectSearch(root: HTMLElement) {
  const tokens = signal<SearchToken[]>(initialTokens);
  const query = signal('');
  const resultCount = signal(18);

  const render = () => <section class="project-search kui-layout kui-section-stack"><TokenSearchField id="project-search-editor" label="Search projects and filters" tokens={tokens.value} placeholder="Search projects" action="search-token-action" /><p class="project-search__status" aria-live="polite">{resultCount.value} results</p></section>;

  const editor = () => root.querySelector<HTMLElement>('#project-search-editor .kui-token-search__editor');
  const runQuery = () => {
    const el = editor();
    if (el) query.value = readTokenSearchField(el);
    // Application-owned parsing, suggestions, and transport use query.value and tokens.value here.
  };
  const onInput = () => runQuery();
  root.addEventListener('input', onInput);

  const disposeActions = delegate(root, 'click', '[data-action="search-token-action"]', (_event, element) => {
    const command = element.dataset.tokenAction;
    const id = element.dataset.tokenId;
    if (command === 'clear') {
      const el = editor();
      if (el) el.textContent = '';
      query.value = '';
      tokens.value = [];
      resultCount.value = 0;
      queueMicrotask(() => { const next = editor(); if (next) placeTokenSearchCaret(next, 'end'); });
      return;
    }
    if (command === 'remove' && id) {
      tokens.value = tokens.value.filter((token) => token.id !== id);
      queueMicrotask(() => { const next = editor(); if (next) placeTokenSearchCaret(next, 'end'); });
    }
    if (command === 'edit' && id) {
      const token = tokens.value.find((candidate) => candidate.id === id);
      const el = editor();
      if (token && el) { el.textContent = `${token.label} `; tokens.value = tokens.value.filter((candidate) => candidate.id !== id); queueMicrotask(() => placeTokenSearchCaret(el, 'end')); }
    }
  });

  return { render, query, tokens, replaceTokens(next: SearchToken[]) { tokens.value = next; queueMicrotask(() => { const el = editor(); if (el) placeTokenSearchCaret(el, 'end'); }); }, dispose() { root.removeEventListener('input', onInput); disposeActions(); } };
}
